WITH catalog_item_profit AS ( SELECT cs.cs_item_sk AS item_sk, SUM(cs.cs_net_profit) AS catalog_profit FROM catalog_sales cs GROUP BY cs.cs_item_sk ), web_item_profit AS ( SELECT ws.ws_item_sk AS item_sk, SUM(ws.ws_net_profit) AS web_profit FROM web_sales ws GROUP BY ws.ws_item_sk ), latest_item_date AS ( SELECT item_sk, MAX(sale_date) AS latest_sale_date FROM ( SELECT cs.cs_item_sk AS item_sk, d.d_date AS sale_date FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk UNION ALL SELECT ws.ws_item_sk AS item_sk, d2.d_date AS sale_date FROM web_sales ws JOIN date_dim d2 ON ws.ws_sold_date_sk = d2.d_date_sk ) t GROUP BY item_sk ), item_comparison AS ( SELECT COALESCE(c.item_sk, w.item_sk) AS item_sk, COALESCE(c.catalog_profit, 0) AS catalog_profit, COALESCE(w.web_profit, 0) AS web_profit, (COALESCE(w.web_profit, 0) - COALESCE(c.catalog_profit, 0)) AS profit_delta, CASE WHEN COALESCE(w.web_profit, 0) > COALESCE(c.catalog_profit, 0) THEN 'Web Higher' WHEN COALESCE(w.web_profit, 0) < COALESCE(c.catalog_profit, 0) THEN 'Catalog Higher' ELSE 'Equal' END AS profit_comparison FROM catalog_item_profit c FULL OUTER JOIN web_item_profit w ON c.item_sk = w.item_sk ) SELECT ic.item_sk, ic.catalog_profit, ic.web_profit, ic.profit_delta, ic.profit_comparison, lid.latest_sale_date, ROW_NUMBER() OVER (ORDER BY ABS(ic.profit_delta) DESC) AS profit_delta_rank, PERCENT_RANK() OVER (ORDER BY ic.profit_delta) AS profit_delta_percentile FROM item_comparison ic LEFT JOIN latest_item_date lid ON ic.item_sk = lid.item_sk WHERE ic.profit_delta <> 0 ORDER BY profit_delta_rank FETCH FIRST 20 ROWS ONLY
